// Compare the browser's bounded models with references generated by real Ashcore Java calls.
import assert from 'node:assert/strict';
import {readFile, readdir, mkdir, mkdtemp, writeFile} from 'node:fs/promises';
import {fileURLToPath} from 'node:url';
import path from 'node:path';
import vm from 'node:vm';
import {spawnSync} from 'node:child_process';

const root = fileURLToPath(new URL('.', import.meta.url));
const context = vm.createContext({window:{}});
vm.runInContext(await readFile(path.join(root,'assets/diagram-math.js'),'utf8'),context,{timeout:1000});
const model = context.window.WikiLabMath;
const verification = path.resolve(root,'../.verification');
await mkdir(verification,{recursive:true});
const work = await mkdtemp(path.join(verification,'wiki-diagrams-'));
const classes = path.join(work,'classes');
await mkdir(classes);
async function javaFiles(directory) {
  const result = [];
  for (const entry of await readdir(directory,{withFileTypes:true})) {
    const file = path.join(directory,entry.name);
    if (entry.isDirectory()) result.push(...await javaFiles(file));
    else if (entry.name.endsWith('.java')) result.push(file);
  }
  return result;
}
const sources = [...await javaFiles(path.resolve(root,'../src/main/java')),path.join(root,'authoring/DiagramFixtures.java')];
const argsFile = path.join(work,'sources.txt');
await writeFile(argsFile,sources.map(file=>`"${file.replaceAll('\\','/')}"`).join('\n'));
const executable = name => process.env.JAVA_HOME ? path.join(process.env.JAVA_HOME,'bin',name + (process.platform === 'win32' ? '.exe' : '')) : name;
function run(name,args) {
  const result = spawnSync(executable(name),args,{encoding:'utf8',windowsHide:true,timeout:60000,maxBuffer:16*1024*1024});
  if (result.error || result.status !== 0) throw new Error(`${name} failed:\n${result.error || ''}\n${result.stdout || ''}${result.stderr || ''}`);
  return result.stdout.trim();
}
run('javac',['--release','21','-encoding','UTF-8','-d',classes,`@${argsFile}`]);
const references = run('java',['-ea','-cp',classes,'DiagramFixtures']).split(/\r?\n/);
const counts = {}, sampleCache = new Map(), noiseCache = new Map();
let rowLabel = '', maximumError = 0;
function near(actual,expected) {
  if (actual === expected) return;
  const error = Math.abs(actual-expected);
  assert.ok(error <= 1e-12,`${rowLabel}: ${actual} != ${expected}`);
  maximumError = Math.max(maximumError,error);
}
function xy(actual,x,y) { near(actual.x,x); near(actual.y,y); }
for (const line of references) {
  const [type,...fields] = line.split('\t'), v=fields.map(Number);
  rowLabel=line; counts[type]=(counts[type]||0)+1;
  if (type==='C') {
    const [x,y,hit,depth,distance,nx,ny,ax,ay,bx,by,touching]=v,c=model.contact(x,y);
    assert.equal(Number(c.hit),hit,line); near(c.depth,depth); near(c.distance,distance);
    if(hit) {
      assert.equal(Number(c.depth===0),touching,line);
      xy(c.normal,nx,ny); xy(c.pointA,ax,ay); xy(c.pointB,bx,by);
      near(c.normal.z,0); near(c.pointA.z,0); near(c.pointB.z,0);
      near(c.pointA.x-c.pointB.x,c.normal.x*c.depth); near(c.pointA.y-c.pointB.y,c.normal.y*c.depth);
    } else { assert.equal(c.normal,null); assert.equal(c.pointA,null); assert.equal(c.pointB,null); }
  } else if (type==='R') {
    const [seed,i,u,w,dx,dy]=v;
    if(!sampleCache.has(seed)) sampleCache.set(seed,{square:model.samples(seed,256),disk:model.samples(seed,256,'disk')});
    const samples=sampleCache.get(seed);
    assert.equal(samples.square.random[i-1].x,u,line); assert.equal(samples.square.random[i-1].y,w,line);
    xy(samples.disk.random[i-1],dx,dy);
  } else if (type==='H') {
    const [i,u,w,dx,dy]=v,samples=sampleCache.get(1337);
    assert.equal(samples.square.halton[i-1].x,u,line); assert.equal(samples.square.halton[i-1].y,w,line);
    xy(samples.disk.halton[i-1],dx,dy);
  } else if (type==='D') {
    const [u,w,x,y]=v; xy(model.disk(u,w),x,y);
  } else if (type==='N') {
    const [seed,frequency,octaves,gain,x,z,value,height]=v;
    if(!noiseCache.has(seed)) noiseCache.set(seed,model.perlin(seed));
    const actual=model.fbm(noiseCache.get(seed),x*frequency,z*frequency,octaves,2,gain);
    near(actual,value); assert.equal(Math.floor(64+actual*12),height,line);
  } else throw new Error(`Unknown fixture ${type}`);
}
for (const count of [1,64,128]) {
  const prefix=model.samples(1337,count);
  assert.deepEqual(prefix.random,sampleCache.get(1337).square.random.slice(0,count));
  assert.deepEqual(prefix.halton,sampleCache.get(1337).square.halton.slice(0,count));
}
for (const samples of sampleCache.values()) {
  assert.deepEqual(samples.square.halton,sampleCache.get(1337).square.halton);
  for(const p of [...samples.disk.random,...samples.disk.halton]) assert.ok(Math.hypot(p.x,p.y)<=1+1e-12);
}
console.log(`PASS ${references.length} Java reference cases: ${JSON.stringify(counts)}; maximum absolute error ${maximumError}.`);
console.log('PASS exact SplitMix64/Halton coordinates, sample prefixes, disk bounds, contact classification and integer terrain heights.');
